<script setup lang="ts">
import {onMounted, reactive, ref} from 'vue'
import {api, readableApiError} from '../../api/client'
import {apiCollection} from '../../api/collections'
import {weightsLabel} from '../../utils/statusLabels'
type Config={id:number;name:string;version:string;weights:Record<string,number>;thresholds:Record<string,number>;preprocessing:Record<string,any>;state:string;editable:boolean;is_published:boolean}
const rows=ref<Config[]>([]), loading=ref(true), busy=ref(false), error=ref(''), success=ref(''), editing=ref(false), editId=ref<number|null>(null)
const factors:Record<string,string>={text:'文字',category:'类别',location:'地点',time:'时间',color:'颜色',brand:'品牌'}
const states:Record<string,string>={ACTIVE:'当前使用',HISTORICAL:'历史已发布',REFERENCED:'已被引用',DRAFT:'未发布草稿'}
const form=reactive({name:'',version:'',weights:{text:.5,category:.15,location:.12,time:.1,color:.08,brand:.05} as Record<string,number>,min_coverage:.6,min_score:.35,time_tau_days:7,time_tolerance_hours:6,dictionary_version:'campus-dict-v1',stop_words:'',custom_words:'',aliases:'{}'})
async function load(){loading.value=true;try{rows.value=(await apiCollection<{data:{items:Config[]}}>('/admin/matching-configs/?page_size=100')).data.items}catch(reason){error.value=readableApiError(reason,'配置读取失败')}finally{loading.value=false}}
function edit(row?:Config,clone=false){
 editId.value=row&&!clone?row.id:null
 Object.assign(form,{name:row?.name??'新匹配配置',version:row&&!clone?row.version:`v-${Date.now()}`,weights:{text:.5,category:.15,location:.12,time:.1,color:.08,brand:.05,...row?.weights},min_coverage:row?.thresholds.min_coverage??.6,min_score:row?.thresholds.min_score??.35,time_tau_days:row?.thresholds.time_tau_days??7,time_tolerance_hours:row?.thresholds.time_tolerance_hours??6,dictionary_version:row?.preprocessing.dictionary_version??'campus-dict-v1',stop_words:(row?.preprocessing.stop_words??[]).join('\n'),custom_words:(row?.preprocessing.custom_words??[]).join('\n'),aliases:JSON.stringify(row?.preprocessing.aliases??{},null,2)})
 editing.value=true;error.value='';success.value=''
}
async function save(){busy.value=true;error.value='';try{
 let aliases:unknown
 try{aliases=JSON.parse(form.aliases)}catch{throw new Error('别名映射请填写有效JSON，例如 {"校图":"图书馆"}。')}
 const words=(value:string)=>value.split(/[\n,，]+/).map(v=>v.trim()).filter(Boolean)
 const body={name:form.name,version:form.version,weights:form.weights,thresholds:{min_coverage:form.min_coverage,min_score:form.min_score,time_tau_days:form.time_tau_days,time_tolerance_hours:form.time_tolerance_hours},preprocessing:{dictionary_version:form.dictionary_version,stop_words:words(form.stop_words),custom_words:words(form.custom_words),aliases}}
 await api('/admin/matching-configs/'+(editId.value?`${editId.value}/`:''),{method:editId.value?'PATCH':'POST',body:JSON.stringify(body)})
 editing.value=false;success.value='草稿已保存';await load()
 }catch(reason){error.value=reason instanceof SyntaxError?reason.message:readableApiError(reason,reason instanceof Error?reason.message:'保存失败')}finally{busy.value=false}}
async function publish(row:Config){if(!window.confirm(`确认${row.state==='HISTORICAL'?'重新启用':'发布'}版本 ${row.version}？`))return;busy.value=true;error.value='';try{await api(`/admin/matching-configs/${row.id}/publish/`,{method:'POST'});success.value='当前使用版本已更新';await load()}catch(reason){error.value=readableApiError(reason,'发布失败')}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="page config-page"><header><h1 class="page-title">匹配参数中心</h1><button class="button button-brand" :disabled="busy" @click="edit()">新建版本</button></header><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="success" role="status">{{success}}</p>
<form v-if="editing" class="panel editor" @submit.prevent="save"><h2>{{editId?'编辑草稿':'新建配置版本'}}</h2><div class="fields"><label>配置名称<input v-model="form.name" required maxlength="100"/></label><label>版本号<input v-model="form.version" required maxlength="32"/></label></div><h3>六因子权重</h3><div class="fields factors"><label v-for="(label,key) in factors" :key="key">{{label}}<input v-model.number="form.weights[key]" type="number" min="0" max="1" step="0.01" required/></label></div><div class="fields"><label>最低覆盖度<input v-model.number="form.min_coverage" type="number" min="0" max="1" step="0.01" required/></label><label>最低匹配分数<input v-model.number="form.min_score" type="number" min="0" max="1" step="0.01" required/></label><label>时间衰减天数<input v-model.number="form.time_tau_days" type="number" min="0.000001" max="36500" step="any" required/></label><label>时间容差（小时）<input v-model.number="form.time_tolerance_hours" type="number" min="0" max="876000" step="any" required/></label><label>词典版本<input v-model="form.dictionary_version" required maxlength="100"/></label><label>停用词<textarea v-model="form.stop_words"/></label><label>自定义词<textarea v-model="form.custom_words"/></label><label>别名映射<textarea v-model="form.aliases" spellcheck="false"/></label></div><footer><button class="button button-brand" :disabled="busy">保存草稿</button><button type="button" class="button button-ghost" :disabled="busy" @click="editing=false">取消</button></footer></form>
<p v-if="loading" role="status">正在读取配置…</p><div v-else class="versions"><article v-for="row in rows" :key="row.id" class="panel version"><div><span class="status-tag">{{states[row.state]??'未发布草稿'}}</span><h2>{{row.name}}</h2><p>{{row.version}}</p><p>{{weightsLabel(row.weights)}}</p></div><div class="actions"><button class="button button-ghost" :disabled="busy" @click="edit(row,true)">基于此版本新建</button><button v-if="row.editable" class="button button-ghost" :disabled="busy" @click="edit(row)">编辑草稿</button><button v-if="!row.is_published" class="button button-brand" :disabled="busy" @click="publish(row)">{{row.state==='HISTORICAL'?'重新启用':'发布'}}</button></div></article></div></div></template>
<style scoped>.config-page header,.version{display:flex;justify-content:space-between;align-items:center;gap:24px}.versions{display:grid;gap:16px;margin-top:24px}.editor,.version{padding:24px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.factors{grid-template-columns:repeat(3,minmax(0,1fr))}label{display:grid;gap:8px}input,textarea{width:100%;box-sizing:border-box;border:1px solid var(--ct-border);border-radius:10px;padding:10px;background:var(--ct-surface);color:var(--ct-text)}textarea{min-height:90px}footer,.actions{display:flex;gap:10px;flex-wrap:wrap}footer{margin-top:20px}.error{color:var(--ct-danger)}.version>div{min-width:0}.version p{overflow-wrap:anywhere}@media(max-width:650px){.config-page header,.version{align-items:flex-start;flex-direction:column}.fields,.factors{grid-template-columns:1fr}.actions{width:100%}}</style>
